import{_ as e,o as r,c as a,a5 as o}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"方法重载（Overload）与方法重写（Override）的区别","description":"方法重载（Overload）和方法重写（Override）是面向对象编程中的两个重要概念，虽然它们名字相似，但它们的功能和用途有很大不同。下面详细描述它们的区别。 方法重载（Overload） 定义 ： 方法重载是指在同一个类中，可以定义多个方法，它们具有相同的方法名，但参数列表。","frontmatter":{"title":"方法重载（Overload）与方法重写（Override）的区别","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"方法重载（Overload）和方法重写（Override）是面向对象编程中的两个重要概念，虽然它们名字相似，但它们的功能和用途有很大不同。下面详细描述它们的区别。 方法重载（Overload） 定义 ： 方法重载是指在同一个类中，可以定义多个方法，它们具有相同的方法名，但参数列表。","sidebarWeight":179,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/面向对象程序设计/Class 的继承/方法重载（Overload）与方法重写（Override）的区别.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/Class 的继承/方法重载（Overload）与方法重写（Override）的区别.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/Class 的继承/方法重载（Overload）与方法重写（Override）的区别.md"}'),d={name:"posts/JavaScript系统教程/03-对象、数组与函数/Class 的继承/方法重载（Overload）与方法重写（Override）的区别.md"};function i(l,t,s,n,v,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<div><h1 id="方法重载-overload-与方法重写-override-的区别" tabindex="-1">方法重载（Overload）与方法重写（Override）的区别 <a class="header-anchor" href="#方法重载-overload-与方法重写-override-的区别" aria-label="Permalink to &quot;方法重载（Overload）与方法重写（Override）的区别&quot;">​</a></h1><blockquote><p>本节目标：理解“方法重载（Overload）与方法重写（Override）的区别”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><h3 id="方法重载-overload-和方法重写-override-是面向对象编程中的两个重要概念-虽然它们名字相似-但它们的功能和用途有很大不同。下面详细描述它们的区别。" tabindex="-1">方法重载（Overload）和方法重写（Override）是面向对象编程中的两个重要概念，虽然它们名字相似，但它们的功能和用途有很大不同。下面详细描述它们的区别。 <a class="header-anchor" href="#方法重载-overload-和方法重写-override-是面向对象编程中的两个重要概念-虽然它们名字相似-但它们的功能和用途有很大不同。下面详细描述它们的区别。" aria-label="Permalink to &quot;方法重载（Overload）和方法重写（Override）是面向对象编程中的两个重要概念，虽然它们名字相似，但它们的功能和用途有很大不同。下面详细描述它们的区别。&quot;">​</a></h3><h4 id="方法重载-overload" tabindex="-1">方法重载（Overload） <a class="header-anchor" href="#方法重载-overload" aria-label="Permalink to &quot;方法重载（Overload）&quot;">​</a></h4><p><strong>定义</strong>： 方法重载是指在同一个类中，可以定义多个方法，它们具有相同的方法名，但参数列表不同（参数类型、参数个数或参数顺序不同）。编译器会根据方法调用时传递的参数来决定具体调用哪个方法。 <strong>特点</strong>：</p><ul><li>发生在同一个类中。</li><li>方法名相同，但参数列表不同。</li><li>可以有不同的返回类型。 <strong>示例</strong>（以 Java 为例）： public class OverloadExample { // 重载方法1：无参数 public void display() { System.out.println(&quot;Display without parameters&quot;); } // 重载方法2：一个参数 public void display(int a) { System.out.println(&quot;Display with one parameter: &quot; + a); } // 重载方法3：两个参数 public void display(int a, int b) { System.out.println(&quot;Display with two parameters: &quot; + a + &quot;, &quot; + b); } public static void main(String[] args) { OverloadExample example = new OverloadExample(); example.display(); // 调用无参数的方法 example.display(10); // 调用一个参数的方法 example.display(10, 20); // 调用两个参数的方法 } }</li></ul><h4 id="方法重写-override" tabindex="-1">方法重写（Override） <a class="header-anchor" href="#方法重写-override" aria-label="Permalink to &quot;方法重写（Override）&quot;">​</a></h4><p><strong>定义</strong>： 方法重写是指子类重新定义父类中的方法，方法名、参数列表和返回类型必须相同，以便子类可以提供父类方法的特定实现。方法重写用于实现多态。 <strong>特点</strong>：</p><ul><li>发生在子类和父类之间。</li><li>方法名、参数列表和返回类型必须相同。</li><li>子类方法的访问修饰符不能低于父类方法的访问修饰符。 <strong>示例</strong>（以 Java 为例）： class Parent { // 父类方法 public void show() { System.out.println(&quot;Show from Parent&quot;); } } class Child extends Parent { // 重写父类方法 @Override public void show() { System.out.println(&quot;Show from Child&quot;); } public static void main(String[] args) { Parent parent = new Parent(); parent.show(); // 调用父类的方法 Child child = new Child(); child.show(); // 调用子类重写的方法 Parent polymorphic = new Child(); polymorphic.show(); // 调用子类重写的方法，体现多态性 } }</li></ul><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>特性</strong></td><td><strong>方法重载（Overload）</strong></td><td><strong>方法重写（Override）</strong></td></tr><tr><td>发生范围</td><td>同一个类中</td><td>子类和父类之间</td></tr><tr><td>方法名</td><td>相同</td><td>相同</td></tr><tr><td>参数列表</td><td>必须不同</td><td>必须相同</td></tr><tr><td>返回类型</td><td>可以相同也可以不同</td><td>必须相同</td></tr><tr><td>访问修饰符</td><td>可以不同</td><td>子类方法的访问修饰符不能低于父类方法的访问修饰符</td></tr><tr><td>使用场景</td><td>提供多种同名方法的不同实现（参数不同）</td><td>子类提供父类方法的特定实现，实现多态性</td></tr></tbody></table><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><ul><li><strong>方法重载</strong>：在同一个类中定义多个同名但参数不同的方法，以实现同一行为的不同变体。重载的方法之间可以有不同的返回类型。</li><li><strong>方法重写</strong>：子类重新定义父类中的方法，以提供特定实现，方法名、参数列表和返回类型必须相同。重写用于实现多态，子类方法的访问修饰符不能低于父类方法的访问修饰符。 理解和正确使用方法重载和方法重写是掌握面向对象编程的重要一步，有助于编写灵活、可维护的代码。</li></ul></div>',1)])])}const u=e(d,[["render",i]]);export{c as __pageData,u as default};
